{
  "xsappname": "saas-app",
  "tenant-mode": "shared",
  "scopes": [
    {
      "name": "$XSAPPNAME.Callback",
      "description": "With this scope set, the callbacks for subscribe, unsubscribe and getDependencies can be called.",
      "grant-as-authority-to-apps": ["$XSAPPNAME(application,sap-provisioning,tenant-onboarding)"]
    }
  ]
}

PUT  /callback/v1.0/tenants/{tenantId}
  -> 200, body: https://subscriber_subdomain-approuter_saas_app.cfapps.eu10.hana.ondemand.com

DELETE /callback/v1.0/tenants/{tenantId}
  -> tenant offboarded

GET  /callback/v1.0/dependencies
  -> 200, body: [ { "xsappname": "<xsappname of a reuse service>" } ]

resources:
  - name: saas-registry
    type: org.cloudfoundry.managed-service
    parameters:
      service: saas-registry
      service-plan: application
      service-name: saas-registry
      config:
        xsappname: ${appname}
        appName: ${appname}
        appUrls:
          getDependencies: https://cis${route-prefix}.${app-domain}/callback/v1.0/dependencies
          onSubscription: https://cis${route-prefix}.${app-domain}/callback/v1.0/tenants/{tenantId}
        displayName: ${saas-display-name}
        description: ${saas-description}
